import { test, expect } from '@playwright/test';

test.describe('Payment Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should display error page on payment timeout', async ({ page }) => {
    // Simulate payment timeout
    await page.fill(getByLabel('Card Number'), '4111 1111 1111 1111');
    await page.fill(getByLabel('Expiration Date'), '12/25');
    await page.fill(getByLabel('CVC'), '123');
    await page.click(getByRole('button', { name: 'Pay Now' }));

    // Wait for timeout and check redirection
    await page.waitForTimeout(5000); // Simulate timeout duration
    await expect(page).toHaveURL('/error');
    await expect(page.getByText('Payment Timeout')).toBeVisible();
  });

  test('should not redirect if payment is successful', async ({ page }) => {
    // Simulate successful payment
    await page.fill(getByLabel('Card Number'), '4111 1111 1111 1111');
    await page.fill(getByLabel('Expiration Date'), '12/25');
    await page.fill(getByLabel('CVC'), '123');
    await page.click(getByRole('button', { name: 'Pay Now' }));

    // Check for successful payment confirmation
    await expect(page).toHaveURL('/payment-success');
    await expect(page.getByText('Payment Successful')).toBeVisible();
  });
});
